// Throwaway hypothesis: skip fbmGrad only when residual amplitude is exactly zero.
import { Color, FloatType, InstancedMesh, Matrix4, Scene, ShaderMaterial, UniformsUtils, Vector3, WebGLRenderTarget } from 'three'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { asteroidDetailWeight } from '/src/core/renderables/DetailedRingStreamingSystem/impostors/impostorDetail'
import { state } from './profile.browser'
import { asteroidShapeFunctions } from '/src/core/materials/shaders/lib/chunks/AsteroidShape'
import { asteroidShapeFunctions as originalShape } from './baseline-AsteroidShape'

export const originalNoise = (source: string) => {
  if (!source.includes(asteroidShapeFunctions)) throw new Error('Expected production residual shape chunk')
  return source.replace(asteroidShapeFunctions, originalShape)
}
const stats = (xs: number[]) => {
  const sorted = xs.slice().sort((a, b) => a - b)
  return { count: xs.length, p50: sorted[Math.ceil(xs.length * .5) - 1], p95: sorted[Math.ceil(xs.length * .95) - 1], max: sorted.at(-1) }
}
export async function compareShape() {
  const c = getInitializedSimulationRuntime()!.container
  const engine = c.get(Tokens.Engine), renderer = c.get(Tokens.Renderer), camera = c.get(Tokens.Camera)
  engine.stop(); engine.renderFrame()
  const snapshot = state(), groups = ['Near', 'L0']
  const savedTarget = renderer.getRenderTarget(), savedColor = renderer.getClearColor(new Color()), savedAlpha = renderer.getClearAlpha()
  const target = new WebGLRenderTarget(renderer.domElement.width, renderer.domElement.height, { type: FloatType })
  const resources: any[] = [target], result: any[] = []
  try {
    for (const group of groups) {
      const scenes = [new Scene(), new Scene()], records: any[] = []
      c.get(Tokens.Scene).traverse((system: any) => {
        if (system.constructor.name !== 'AsteroidRingSystem' || !system.visible) return
        for (let parent = system.parent; parent; parent = parent.parent) if (!parent.visible) return
        for (const source of group === 'Near' ? system.pool.nearMeshes : system.pool.geometryMeshes) {
          if (!source.count || !source.visible) continue
          const matrix = new Matrix4(), localCamera = camera.getWorldPosition(new Vector3()).applyMatrix4(source.matrixWorld.clone().invert())
          const origin = source.geometry.getAttribute('instanceOrigin'), detailEnd = source.geometry.getAttribute('instanceDetailEnd'), detailMix = source.geometry.getAttribute('instanceDetailMix')
          const u = source.material.uniforms, vertices = source.geometry.getAttribute('position').count
          let active = 0, zeroWeight = 0
          for (let i = 0; i < source.count; i++) {
            matrix.fromArray(source.instanceMatrix.array, i * 16)
            if (Math.abs(matrix.determinant()) < 1e-20) continue
            active++
            const delta = new Vector3().setFromMatrixPosition(matrix).add(new Vector3(origin.getX(i), origin.getY(i), origin.getZ(i))).sub(localCamera)
            const distance = u.uLodVolumetric.value > .5 ? delta.length() : Math.hypot(delta.x, delta.z)
            const weight = u.uImpostorReady.value > .5 && detailEnd.getX(i) > 0
              ? asteroidDetailWeight(distance, detailEnd.getX(i), detailMix.getX(i), u.uDetailStartFraction.value) : 1
            if (weight === 0) zeroWeight++
          }
          records.push({ mesh: source.name, submitted: source.count, active, zeroWeight, vertices,
            indices: source.geometry.index?.count, shapeMin: u.uShapeAmpMin.value, shapeMax: u.uShapeAmpMax.value })
          const uniforms: any = {}
          for (const [name, uniform] of Object.entries(source.material.uniforms) as any) {
            uniforms[name] = uniform.value?.isTexture ? { value: uniform.value } : UniformsUtils.clone({ uniform }).uniform
          }
          for (let mode = 0; mode < 2; mode++) {
            const material = new ShaderMaterial()
            material.copy(source.material); material.uniforms = uniforms
            material.defaultAttributeValues = { ...source.material.defaultAttributeValues }
            if (!mode) material.vertexShader = originalNoise(material.vertexShader)
            const mesh = new InstancedMesh(source.geometry, material, source.count)
            mesh.instanceMatrix.array.set(source.instanceMatrix.array.subarray(0, source.count * 16))
            mesh.count = source.count; mesh.frustumCulled = false; mesh.matrixAutoUpdate = false
            mesh.matrix.copy(source.matrixWorld); scenes[mode].add(mesh)
            resources.push(mesh, material)
          }
        }
      })
      const render = (mode: number) => {
        renderer.setRenderTarget(target); renderer.setClearColor(0, 0); renderer.clear(); renderer.render(scenes[mode], camera)
      }
      const read = () => { const p = new Float32Array(target.width * target.height * 4); renderer.readRenderTargetPixels(target, 0, 0, target.width, target.height, p); return p }
      render(0); const reference = read()
      render(1); const actual = read()
      const referenceBits = new Uint32Array(reference.buffer), actualBits = new Uint32Array(actual.buffer)
      let maxError = 0, different = 0, differentBits = 0, signal = 0, error = 0
      for (let i = 0; i < actual.length; i++) {
        if (!Number.isFinite(actual[i]) || !Number.isFinite(reference[i])) throw new Error('Nonfinite shape pixels')
        const delta = Math.abs(actual[i] - reference[i]); maxError = Math.max(maxError, delta); error += delta
        if (delta) different++; signal += Math.abs(reference[i])
        if (referenceBits[i] !== actualBits[i]) differentBits++
      }
      if (different || differentBits || !signal) throw new Error('Production shape changed the frozen HDR image or reference was empty')
      const measure = async (mode: number) => {
        const timer = new GpuTimer(renderer.getContext() as WebGL2RenderingContext), samples: number[] = []
        try {
          for (let i = 0; i < 6; i++) { render(mode); await new Promise(r => setTimeout(r, 0)) }
          for (let i = 0; i < 32; i++) { timer.measure(() => render(mode)); await new Promise(r => setTimeout(r, 0)); samples.push(...timer.poll()) }
          const deadline = performance.now() + 30000
          while (timer.pendingCount) { if (performance.now() > deadline) throw new Error('GPU timeout'); await new Promise(r => setTimeout(r, 10)); samples.push(...timer.poll()) }
          return { ...stats(samples), samples }
        } finally { timer.dispose() }
      }
      const row = { group, records, image: { maxError, different, differentBits, signal, relativeError: error / Math.max(signal, 1e-20) },
        baseline: await measure(0), guarded: await measure(1), baselineRepeat: await measure(0), guardedRepeat: await measure(1) }
      result.push(row); console.info('SHAPE', JSON.stringify(row))
    }
    if (renderer.getContext().getError()) throw new Error('Shape comparison WebGL error')
    return { snapshot, result }
  } finally {
    for (const resource of resources) resource.dispose()
    renderer.setRenderTarget(savedTarget); renderer.setClearColor(savedColor, savedAlpha); engine.start()
  }
}

