import { createServer } from 'vite'
import { chromium } from '@playwright/test'
import { writeFile } from 'node:fs/promises'
Object.assign(process.env, { VITE_FS_DRIVER: 's3', VITE_S3_URL: 'https://storage.yandexcloud.net',
  VITE_FILE_BUCKET: 'textures', VITE_SHOW_STATS_PANEL: 'false', VITE_SKY_SOURCE: 'gaia' })
const report = { startedAt: new Date().toISOString(), rows: [], errors: [], warnings: [], assetFailures: [], outcome: 'failed' }
let server, browser
try {
  server = await createServer({ server: { host: '127.0.0.1', port: 8094, strictPort: true, hmr: false } }); await server.listen()
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`) })
  page.on('requestfailed', r => { if (!/ERR_ABORTED/.test(r.failure()?.errorText ?? '')) report.assetFailures.push(`${r.failure()?.errorText} ${r.url()}`) })
  await page.goto('http://127.0.0.1:8094/'); await page.getByRole('button', { name: /^Run / }).first().waitFor()
  for (const [id, views] of [[13, [[135, 'belt']]], [12, [[127, 'belt']]]]) {
    console.log('Starting', id)
    await page.evaluate(async id => Promise.race([(await import('/tests/browser/scenarioSoak.browser.ts')).selectScenario(id),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Startup timeout')), 180000))]), id)
    for (const [actor, kind] of views) {
      const selectedView = await page.evaluate(async args => (await import('/benchmark-results/heavy-scenes/profile.browser.ts')).setView(...args), [actor, kind])
      await page.waitForTimeout(5000)
      const timings = await page.evaluate(async () => (await import('/benchmark-results/heavy-scenes/shape-zero-production.browser.ts')).compareShape())
      if (/SwiftShader|llvmpipe|software/i.test(timings.snapshot.renderer)) throw new Error('Software renderer')
      console.log(JSON.stringify({ id, groups: timings.result.map(({ records, ...r }) => r) }))
      const moving = await page.evaluate(async () => (await import('/benchmark-results/heavy-scenes/shape-motion.browser.ts')).movingShape())
      console.log(JSON.stringify({ id, motion: moving.groups }))
      report.rows.push({ id, view: selectedView, timings, moving })
      await writeFile('benchmark-results/heavy-scenes/shape-zero-production.json', JSON.stringify(report, null, 2))
    }
    await page.evaluate(async () => (await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if (report.errors.length || report.assetFailures.length) throw new Error('Browser or asset errors')
  }
  report.outcome = 'completed'
} catch (e) { report.failure = e.stack || e.message; console.error(e); process.exitCode = 1 }
finally {
  report.finishedAt = new Date().toISOString()
  await writeFile('benchmark-results/heavy-scenes/shape-zero-production.json', JSON.stringify(report, null, 2))
  await browser?.close(); await server?.close()
}

